isfold-gap1 : (m : ℕ) → (n : ℕ) → {p : ℕ} → fold p (_+_ n) (suc m) ≡ suc m * n + p
2 clause(s), 2 step(s), lemmas: (none)

clause isfold-gap1 zero n
  goal: fold p (_+_ n) 1 ≡ 1 * n + p
  1. fold p (_+_ n) 1 ≡ 1 * n + p
       by sym {!!}

clause isfold-gap1 (suc m) n {p}
  goal: fold p (_+_ n) (suc (suc m)) ≡ suc (suc m) * n + p
  1. fold p (_+_ n) (suc (suc m)) ≡ suc (suc m) * n + p
       by {!!}

*+-is-fold : ∀ m n {p} → fold p (n +_) m ≡ m * n + p
2 clause(s), 2 step(s), lemmas: (none)

clause *+-is-fold zero n {p}
  goal: fold p (_+_ n) zero ≡ zero * n + p
  1. fold p (_+_ n) zero ≡ zero * n + p
       by {!!}

clause *+-is-fold (suc m) n {p}
  goal: fold p (_+_ n) (suc m) ≡ suc m * n + p
  1. fold p (_+_ n) (suc m) ≡ suc m * n + p
       by {!!}

isfoldgap1-gap1 zero    = 0-lemma {p}
isfoldgap1-gap1 (suc m) = 1+m-lemma {m} {n} {p}
isfoldgap1-gap1 (suc (suc m)) = 2+m-lemma {m} {n} {p}

